registerRefData('nsw-cond-n-461',{"id":461,"pan":null,"ref":"16-2024-420-1","address":"31 Phillip Street Raymond Terrace 2324,35 Phillip Street Raymond Terrace 2324,37 Phillip Street Raymond Terrace 2324,11 Edinburgh Street Raymond Terrace 2324","description":"Multi-dwelling housing","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-02-21","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-312!20250220T231319.563 GMT","sha256":"7112eaa79f2ee64d997138874106fc1d229c3b87b5af2a338de6f31b4ea09eba","pages":36,"layout":"numbered","n":100,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/461.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/multi-dwelling-housing-14","lga":"PORT STEPHENS","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-312 - Port Stephens - DA 16-2024 -420 -1","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Demolition of three dwellings, vegetation removal, 3 into 2 lot Torrens\ntitle subdivision, construction of 13x multi dwelling houses","stage":"general","stage_basis":"heading","page":4},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS Lots 130, 129 & 151 DP 31774","text":"31, 35 & 37 Phillip Street, Raymond Terrace 2324","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Hume Community Housing Association Company Limited","text":"Homes NSW","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Private infrastructure and community facilities over $5 million","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Biodiversity and\nconservation) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards)\n2021\no State Environmental Planning Policy (Housing) 2021\no State Environmental Planning Policy (Sustainable Buildings)\n2022\no Port Stephens Local Environmental Plan 2013\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Port Stephens Development Control Plan 2014\n• Planning agreements: Draft Remediation of Land State\nEnvironmental Planning Policy\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021 - Section 61(1) demolition of buildings\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and\neconomic impacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental\nPlanning and Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically\nsustainable development","stage":"general","stage_basis":"heading","page":4},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 7 February 2025\n• Written request to vary a development standard(s) in the\nPSLEP 2013\n• Written submissions during public exhibition: 0\n• Total number of unique submissions received by way of objection:\n0","stage":"general","stage_basis":"heading","page":4},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Preliminary Briefing: 18 November 2024\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony\nMcNamara\no C ouncil assessment staff: Emily Allen, Christopher Primrose\no Applicant Representatives: Kelly Preston, Wei Ji, Penny Smith,\nTarshan Ahmed, Rabi Yue Sui, Noah El-Sabsabi, Jesse Wilson\n• Site inspection:\nRoberta Ryan: 14 November 2024\nTony McNamara: 22 January 2025\nGiacomo Arnott: 23 December 2024\n• Final briefing to discuss council’s recommendation: 17 February\n2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Tony\nMcNamara, Giacomo Arnott, Leah Anderson\no C ouncil assessment staff : Christopher Primrose, Emily Allen\nand Molly Compton\no A pplicant representatives: Bryce Luke, Wei Ji, Penny Smith,\nTarshan Ahmed, Rabi Yue Sui, Noah El-Sabsabi, Jesse Wilson","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":5},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"1","code":null,"number":"1","title":"Approved plans and supporting documentation","text":"Development must be carried out in accordance with the following approved plans and\ndocuments, except where the conditions of this consent expressly require otherwise.\nApproved plans\nPlan number Revision number Plan title Drawn by Date of plan\nDA02 Sheet 3 of\n33 A Demolition Plan Stanton Dahl\nArchitects\n17/01/2025\nDA03 Sheet 4 of\n33 P24 Cut & Fill Plan Stanton Dahl\nArchitects\n16/01/2025\nDA05 Sheet 5 of\n33 P24 Site & External\nWorks Plan\nStanton Dahl\nArchitects\n16/01/2025\nDA07 Sheet 7 of\n33 P24 Ground Floor Plans Stanton Dahl\nArchitects\n16/01/2025\nDA08 Sheet 8 of\n33 P24 Level 1 Floor Plans Stanton Dahl\nArchitects\n16/01/2025\nDA09 Sheet 9 of\n33 P24 Roof Plan Stanton Dahl\nArchitects\n16/01/2025\nDA10 Sheet 10\nof 33\nP24 Elevations 1 Stanton Dahl\nArchitects\n16/01/2025\nDA11 Sheet 11\nof 33\nP24 Elevations 2 Stanton Dahl\nArchitects\n16/01/2025\nDA12 Sheet 12\nof 33\nP24 Sections 1 Stanton Dahl\nArchitects\n16/01/2025\nDA13 Sheet 13\nof 33\nP24 Sections 2 Stanton Dahl\nArchitects\n16/01/2025\nDA18 Sheet 18\nof 33\nP24 External Finishes\nSelection\nStanton Dahl\nArchitects\n16/01/2025\nL01 Sheet 1 of 2 5 Landscape Plan Bontanique Design 15/12/2024\nB2286SUB-A\nSheet 1 of 1\nA Plan of Proposed\nSubdivision\nParker Scanlon 30/10/2024\n230392 DAESM2 1 Environmental Site\nManagement Plan\nGreenview\nConsulting\n28/06/2024\n230392 DA C02 3 Ground Floor\nDrainage Plan\nGreenview\nConsulting\n19/12/2024\n230392 DA C03 3 Site Stormwater\nDetails Sheet 1\nGreenview\nConsulting\n19/12/2024\n230392 DA C04 3 Site Stormwater\nDetails Sheet 2\nGreenview\nConsulting\n19/12/2024\n230392 DA C05 3 Site Stormwater\nDetails Sheet 3\nGreenview\nConsulting\n19/12/2024\nSCHEDULE 2\nApproved Documents\nDocument title Version No. Prepared by Dated\nArborist Report - Abacus Tree Services 17 January 2025\nAcoustic DA Report R01v2 PKA Acoustic Consulting 19 July 2024\nGeotechnical and Acid Sulfate\nSoil Investigation Report\n- NEO Consulting Pty Ltd 19 June 2024\nWaste Management Plan -\nREF-23082\n- Dickens Solutions December 2024\nIn the event of any inconsistency with the approved plans and a condition of this consent, the\ncondition prevails.","stage":"general","stage_basis":"heading","page":6},{"label":"2","code":null,"number":"2","title":"General Terms of Approval","text":"The General Terms of Approval from state authorities must be complied with prior to, during,\nand at the completion of the development.\nThe General Terms of Approval are:\n1. NSW Rural Fire Service, referenced DA20240829003546-Original-1, dated 1 October 2024\nA copy of the General Terms of Approval is attached to this determination notice.","stage":"general","stage_basis":"heading","page":7},{"label":"3","code":null,"number":"3","title":"Protection of existing vegetation and natural landscape features","text":"No vegetation or natural landscape features other than that authorized for removal, pruning\nby this Consent must be disturbed, damaged, or removed. No additional works or\naccess/parking routes transecting the protected vegetation must be undertaken without\nCouncil Approval.\nProtection of trees to be retained must be in accordance with AS490 ‘Protection of Trees on\nDevelopment Sites’ and the following:\na) No existing nature strip(s), street tree(s), tree guard(s), protective bollard(s), garden bed\nsurrounds or root barrier installation(s) must be disturbed, relocated, removed or damaged\nduring earthworks, demolition, excavation (including any driveway installation), construction,\nmaintenance and/or establishment works applicable to this consent, without Council\nagreement and/or consent.","stage":"general","stage_basis":"heading","page":7},{"label":"4","code":null,"number":"4","title":"Building Code of Australia","text":"All building work must be carried out in accordance with the BCA. In this clause, a reference to\nthe BCA is a reference to that Code as in force on the date the application for the relevant\nConstruction Certificate is made.","stage":"general","stage_basis":"heading","page":8},{"label":"5","code":null,"number":"5","title":"Sign on Building","text":"Except in the case of work only carried out to the interior of a building or Crown building work,\na sign must be erected in a prominent position on the site showing the name, address and\ntelephone number of the Principal Certifying Authority for the work, the name of any principal\ncontractor and their after-hours contact number, and must contain a statement that\nunauthorised entry to the site is prohibited.\nThe sign must be maintained while the work is being carried out and is to be removed when\nthe work is completed.","stage":"general","stage_basis":"heading","page":8},{"label":"6","code":null,"number":"6","title":"Driveway Gradients and Design","text":"For all driveways that relate to development for the purposes of a dwelling house, the\ndriveway gradient and design must comply with AS 2890.1 'Off street Car Parking’ and:\na) a Works on Public Infrastructure (Driveway) approval must be obtained prior to the\ncommencement of any works.\nDetails demonstrating compliance must be provided to the Certifying Authority.","stage":"during_work","stage_basis":"heading","page":8},{"label":"7","code":null,"number":"7","title":"Tree Removal/Pruning","text":"The trees 1-6 and 9-13, as identified on Page 37 of the Arborist Report, prepared by Abacus\nTree Services and dated 17 January 2025 are approved for removal.\nRemoval of existing vegetation is not to occur until the issue of the Construction Certificate or\nSubdivision Works Certificate, whichever occurs first.","stage":"during_work","stage_basis":"heading","page":8},{"label":"8","code":null,"number":"8","title":"Demolition Works","text":"All demolition works are to be carried out in accordance with Australian Standard AS 2601\n‘The demolition of Structures’. All waste materials are to be either recycled or disposed of to a\nlicensed waste facility.\nAny asbestos containing material encountered during demolition or works, is to be removed in\naccordance with the requirements of Safe Work NSW and disposed of to an appropriately\nlicenced waste facility.\nEvidence is to be provided to the Certifying Authority demonstrating that asbestos waste has\nbeen disposed of in accordance with this condition.","stage":"during_work","stage_basis":"heading","page":9},{"label":"9","code":null,"number":"9","title":"Dilapidation Report","text":"Before any site work comments, including any demolition or tree removal, a dilapidation\nreport must be prepared by a suitably qualified engineer detailing the structural condition of\nadjoining buildings, structures or works, and public land to the satisfaction of the principal\ncertifier.\nWhere access has not been granted to any adjoining properties to prepare the dilapidation\nreport, the report must be based on a survey of what can be observed externally and\ndemonstrate, in writing, to the satisfaction of the principal certifiers, that all reasonable steps\nwere taken to obtain access to the adjoining properties.\nBuilding Work","stage":"during_work","stage_basis":"heading","page":9},{"label":"10","code":null,"number":"10","title":"Construction Certificate","text":"The following information must be provided to the Certifying Authority with the Construction\nCertificate application:\na) Amended stormwater management plan which directs all stormwater generated from\nthe site to the on-site detention systems prior to leaving the site, including the\ninternal driveway access from Phillip Street.\nb) Driveway line marking and signage indicating appropriate right-of-way for vehicle\negress and ingress to the site.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"11","code":null,"number":"11","title":"Erosion and sediment controls plan","text":"Before the issue of a Construction Certificate, an erosion and sediment control plan must be\nprepared by a suitably qualified person in accordance with the following documents and\nprovided to the certifier:\n1. the guidelines set out in 'Managing Urban Stormwater: Soils and Construction’\nprepared by Landcom (the Blue Book) (as amended from time to time), and\n2. The ‘Do it Right On-Site, Soil and Water Management for the Construction Industry'\n(Southern Sydney Regional Organisation of Councils and the Natural Heritage Trust)\n(as amended from time to time).","stage":"before_cc","stage_basis":"heading","page":10},{"label":"12","code":null,"number":"12","title":"Waste Management Plan requirements","text":"Before the issue of a Construction Certificate, a waste management plan for the development\nmust be prepared and provided to the certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"13","code":null,"number":"13","title":"Section 7.11 development contributions","text":"A monetary contribution is to be paid to Council for the provision of 10 additional dwellings (a\nconcession has been provided for the three existing), pursuant to Section 7.11 of the\nEnvironmental Planning & Assessment Act 1979 and the Port Stephens Local Infrastructure\nContributions Plan 2020 towards the provision of the following public facilities:\nFacility Per Lot/Dwelling Total $\nCivic Administration - Plan\nManagement\n$655 $6,550\nCivic Administration - Works Depot $1,268 $12,680\nTown Centre Upgrades $3,414 $34,140\nPublic Open Space, parks and\nreserves\n$861 $8,610\nSports and Leisure facilities $1,846 $18,460\nCultural and Community Facilities $443 $4,430\nRoad Works $5,708 $57,080\nShared Paths $4,239 $42,390\nBus Facilities $18 $180\nFire and Emergency Services $36 $360\nFlood & Drainage $720 $7,200\nKings Hill Urban Release Area $792 $7,920\nTotal $20,000 $200,000\nPayment of the above must apply to the Development Application as follows:\na) Subdivision and Building work - prior to the issue of the Construction Certificate or\nSubdivision Certificate, whichever occurs first.\nNote: The amount of contribution payable under this condition has been calculated at the date\nof consent. In accordance with the provisions of the Contributions Plan, this amount must be\nindexed at the time of actual payment in accordance with the applicable Index.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"14","code":null,"number":"14","title":"Long Service Levy","text":"Before the issue of a Construction Certificate, the long service levy of $15,225.00, as calculated\nat the date of this consent, must be paid to the Long Service Corporation under the Building\nand Construction industry Long Service Payments Act 1986, section 34, and evidence of the\npayment is to be provided to the principal certifier","stage":"before_cc","stage_basis":"heading","page":11},{"label":"15","code":null,"number":"15","title":"Stormwater/Drainage Plans","text":"Detailed stormwater drainage plans must be prepared by a qualified Engineer in accordance\nwith the approved plans, Council’s Infrastructure Specifications and the current Australian\nRainfall and Runoff guidelines using the Hydrologic Soil Mapping data for Port Stephens\n(available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority, prior to the\nissue of the Construction Certificate.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of\nworks within an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"16","code":null,"number":"16","title":"Stormwater System Operation and Maintenance Procedure Plan","text":"An Operation and Maintenance Plan for the stormwater system must be prepared by a\nqualified engineer detailing a regular maintenance program for pollution control devices,\ncovering inspection, cleaning and waste disposal.\nDetails demonstrating compliance must be provided to the Certifying Authority.\nCondition reasons: Where a stormwater system is proposed which includes stormwater\ndevice(s) that require inspection and maintenance.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"17","code":null,"number":"17","title":"Roads Act Approval","text":"Before the issue of a Construction Certificate, for construction/reconstruction of Council\ninfrastructure, including vehicular crossings, footpath, kerb and gutter, stormwater drainage,\nan application must be made for a Roadworks Permit under Section 138 of the Roads Act\n1993. The following information must be provided to Council as the Roads Authority with the\nRoads Act application:\na) Stormwater connections to public infrastructure\nb) Footpath to be designed across the full frontage of the development site within Phillip\nStreet, connecting to the existing bus stop and including kerb ramp(s).","stage":"before_cc","stage_basis":"heading","page":12},{"label":"18","code":null,"number":"18","title":"Civil engineering plans","text":"Before the issue of a Construction Certificate, civil engineering plans prepared by a qualified\nEngineer, indicating any required drainage, roads, accessways, earthworks, pavement design,\nstreet lighting, details of line-marking, traffic management, water quality and quantity\nfacilities including stormwater detention and disposal, must be prepared in accordance with\nthe approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of\nworks within an existing road reserve.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"19","code":null,"number":"19","title":"Construction Site Management Plan","text":"Before the issue of a Construction Certificate, a construction site management plan must be\nprepared, and provided to the principal certifier. The plan must include the following matters:\na. The location and materials for protective fencing and hoardings on the perimeter of\nthe site;\nb. Provisions for public safety;\nc. Pedestrian and vehicular site access points and construction activity zones;\nd. Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements; and\niii. Measures to ensure pedestrian safety near the site;\ne. Details of bulk earthworks to be carried out;\nf. The location of site storage areas and sheds;\ng. The equipment used to carry out works;\nh. The location of a garbage container with a tight-fitting lid;\ni. Dust, noise and vibration control measures;\nj. The location of temporary toilets;\nk. The protective measures for the preservation of trees on-site and in adjoining public\nareas including measures in accordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An applicable Development Control Plan;\niii. An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on site at all times while work\nis being carried out.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"20","code":null,"number":"20","title":"Flood Design Measures","text":"Before the issue of a Construction Certificate, evidence that the following flood related design\nprecautions have been adhered to in the detailed design must be submitted to the Principal\nCertifying Authority:\na) In sewered areas some plumbing fixtures may be located below the Flood Planning\nLevel (FPL). Where this occurs sanitary drainage is to be fitted with a reflux valve to\nprotect against internal sewage surcharge;\nb) All materials stored at the site and capable of causing harm to the environment must\nbe stored at a level not less than the FPL or suitable bunding must be placed around\nsuch materials to a minimum of the FPL;\nc) All building materials, equipment, ducting, etc., below the FPL must be flood\ncompatible and ducting must be provided with openings for drainage and cleaning;\nd) All main power supply, heating and air conditioning service installations, including\nmeters must be located above the FPL. All electrical equipment installed below the\nFPL must be capable of disconnection by a single plug from the power supply;\ne) All electrical wiring below the FPL must be suitable for continuous submergence in\nwater. All conduits below the FPL must be self-draining. Earth core leakage systems or\nsafety switches are to be installed;\nf) Wherever possible, the premises must be designed to ensure that plant, equipment,\nstorage tanks or other fixtures or fittings liable to damage by floods are located above\nthe FPL or be moveable to levels above the FPL. Should this not have the ability to\noccur, they shall be suitable for submergence in water and securely anchored to\novercome buoyancy and movement. All storage tanks must be vented to an elevation\nabove the FPL.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"21","code":null,"number":"21","title":"Retaining Walls","text":"All retaining walls within 1m of a boundary and exceeding 600mm in height must be designed\nand certified by a suitably qualified Structural Engineer. All retaining walls must be wholly\ncontained within the lot boundaries.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to the\nissue of the Construction Certificate.\nCondition reasons: To ensure that retaining walls in proximity to the boundary and over a\nheight are designed and certified by a suitably qualified engineer.\nBefore building and subdivision work commences","stage":"before_cc","stage_basis":"heading","page":13},{"label":"22","code":null,"number":"22","title":"All Weather Access","text":"A 3m wide all-weather vehicle access is to be provided from the kerb and gutter to the\nbuilding under construction for the delivery of materials and use by trades people.\nNo materials, waste or the like are to be stored on the all-weather access at any time.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"23","code":null,"number":"23","title":"Erosion and sediment controls in place","text":"Before any site work commences, the certifier must be satisfied the erosion and sediment\ncontrols in the erosion and sediment control plan are in place. These controls must remain in\nplace until any bare earth has been re-stabilized in accordance with 'Managing Urban\nStormwater: Soils and Construction’ prepared by Landcom (the Blue Book) (as amended from\ntime to time).","stage":"before_cc","stage_basis":"heading","page":14},{"label":"24","code":null,"number":"24","title":"Tree protection measures","text":"Before any site work commences, the principal certifier, or Council where a principal certifier\nis not required, must be satisfied the measures for tree protection detailed in the construction\nsite management plan and this determination are in place.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"25","code":null,"number":"25","title":"Notice Commencement of Work","text":"Notice must be given to Council and the Principal Certifier, if not the Council, of the person’s\nintention to commence the erection of the building or undertake subdivision work at least two\ndays prior to subdivision and/or building works commencing in accordance with Sections 6.6\n(2) and 6.12 (2) (c) of the Environmental Planning and Assessment Act 1979 and Section 59 of\nthe Environmental Planning and Assessment (Development Certification and Fire Safety)\nRegulation 2021. The notice must include:\na) The name and address of the person;\nb) A description of the work to be carried out;\nc) The address of the land on which the work is to be carried out;\nd) The Registered numbers and date of issue of the development consent and\nconstruction certificate;\ne) A statement signed by or on behalf of the principal certifier that all conditions of the\nconsent that must be satisfied before work commences have been satisfied; and\nf) The date on which the work is intended to commence.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"26","code":null,"number":"26","title":"Construction Certificate Required","text":"In accordance with the provisions of Section 6.7 of the Environmental Planning & Assessment\nAct 1979 (EP&A Act 1979), construction or subdivision works approved by this consent must\nnot commence until the following has been satisfied:\na) A Construction Certificate has been issued by a Consent Authority;\nb) A Principal Certifying Authority (PCA) has been appointed by the person having benefit\nof the development consent in accordance with Section 6.5 of the EP&A Act 1979;\nand\nc) The PCA is notified in writing of the name and contractor license number of the\nowner/building intending to carry out the approved work.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"27","code":null,"number":"27","title":"Subdivision Works Certificate Required","text":"In accordance with the provisions of Section 6.13 of the Environmental Planning & Assessment\nAct 1979 (EP&A Act 1979), subdivision works approved by this consent must not commence\nuntil the following has been satisfied:\na) a Subdivision Works Certificate has been issued by a Consent Authority;\nb) a Principal Certifying Authority (PCA) has been appointed by the person having benefit\nof the development consent in accordance with Section 6.5 of the EP&A Act 1979; and\nc) the PCA is notified in writing of the name and contractor licence number of the\nowner/builder intending to carry out the approved works.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"28","code":null,"number":"28","title":"Notice of Principal Certifying Authority Appointment","text":"The Principal Certifier for this development must give notice must be given to the consent\nauthority and Council, where the Council is not the consent authority, at least two days prior\nto subdivision and/or building works commencing in accordance with Section 6.6 (2) (a) of the\nEnvironmental Planning and Assessment Act 1979 and Section 57 of the Environmental\nPlanning and Assessment (Development Certification and Fire Safety) Regulation 2021. The\nnotice must include:\na) A description of the work to be carried out;\nb) The address of the land on which the work is to be carried out;\nc) The Registered number and date of issue of the relevant development consent;\nd) The name and address of the Principal Certifier and the person who appointed the\nprincipal certifier;\ne) If the principal certifier is a registered certifier\ni) The certifier’s registration number, and\nii) A statement signed by the registered certifier to the effect that the certifier\nconsents to be appointed as principal certifier, and\niii) A telephone number on which the certifier may be contacted for business\npurposes.\nThe notice must be lodged on the NSW Planning Portal.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"29","code":null,"number":"29","title":"Damage report - Public Infrastructure","text":"The applicant is required to notify Council in writing of any existing damage to public\ninfrastructure (including landscaping) within the vicinity of the development, the absence of\nsuch notification signifies that no damage exists","stage":"before_cc","stage_basis":"heading","page":16},{"label":"30","code":null,"number":"30","title":"Public liability insurance","text":"The owner or contractor must take out a Public Liability Insurance Policy with a minimum\ncover of $20 million in relation to the occupation of, and works within, public property (i.e.\nkerbs, gutters, footpaths, walkways, reserves, etc.) for the full duration of the proposed works.\nEvidence of this Policy must be provided to Council and the Certifying Authority.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"31","code":null,"number":"31","title":"Site is to be secured","text":"The site must be secured and fenced to the satisfaction of the Principal Certifying Authority.\nAll hoarding, fencing, or awnings associated with securing the site during construction is to be\nremoved upon the completion of works.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"32","code":null,"number":"32","title":"Home Building Act requirements","text":"Residential building work within the meaning of the Home Building Act 1989 must not be\ncarried out unless the principal certifier for the development to which the work related (not\nbeing the council) has given the council written notice of the following information -\na) In the case of work for which a principal contractor is required to be appointed -\ni) The name and license number of the principal contractor, and\nii) The name of the insurer by which the work is insured under Part 6 of that Act,\nb) In the case of work to be done by an owner-builder -\ni) The name of the owner-builder, and\nii) If the owner-builder is required to hold an owner-builder permit under that Act,\nthe number of the owner-builder permit.\nIf arrangements for doing the residential building work are changed while the work is in\nprogress so that the information notified becomes out of date, further work must not be\ncarried out unless the principal certifier for the development to which the work relates (not\nbeing the certifier) has given the Council written notice of the updated information.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"33","code":null,"number":"33","title":"Compliance with Home Building Act (if applicable)","text":"In the case of residential building work for which the Home building Act 1989 requires there to\nbe a contract of insurance in force in accordance with Part 6 of that Act, and that such a\ncontract of insurance is in force before any building work authorised to be carried out by this\nconsent commences.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"34","code":null,"number":"34","title":"Notice regarding dilapidation report","text":"Before the commencement of any site or building work, the principal certifier must ensure the\nadjoining building owner(s) is provided with a copy of the dilapidation report for their\nproperty(ies) no less than seven (7) days before the commencement of any site or building\nworks and provide a copy of the report to the Council at the same time.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"35","code":null,"number":"35","title":"Rubbish Generated from the Development","text":"Where not already available, a waste containment facility is to be established on site. The\nfacility is to be regularly emptied and maintained for the duration of works.\nNo rubbish must be stockpiled in a manner which facilitates the rubbish to be blown or\nwashed off site. The site must be cleared of all building refuse and spoil immediately upon\ncompletion of the development.\nDuring building and subdivision work","stage":"before_cc","stage_basis":"heading","page":17},{"label":"36","code":null,"number":"36","title":"Discovery of relics and Aboriginal objects","text":"While site works is being carried out, if a person reasonably suspects a relic or Aboriginal\nobject is discovered:\na. The work in the area of the discovery must cease immediately;\nb. The following must be notified -\ni. For a relic - the Heritage Council; or\nii. For an Aboriginal object - the person who is the authority for the protection of\nAboriginal objects and Aboriginal places in New South Wales under the National\nParks and Wildlife Act 1974, Section 85.\nSite works may recommence at a time conformed in writing by:\na. For a relic - the Heritage Council; or\nb. For an Aboriginal object - the person who is the authority for the protection of\nAboriginal objects and Aboriginal places in New South Wales under the National Parks\nand Wildlife Act 1974, section 85","stage":"before_cc","stage_basis":"heading","page":18},{"label":"37","code":null,"number":"37","title":"Unexpected Finds Contingency (General)","text":"Should any suspect materials (identified by unusual staining, odour, discolouration or\ninclusions such as building rubble, asbestos, ash material, etc.) be encountered during any\nstage of works (including earthworks, site preparation or construction works, etc.), such works\nmust cease immediately until a qualified environmental specialist has be contacted and\nconducted a thorough assessment.\nIn the event that contamination is identified as a result of this assessment and if remediation\nis required, all works must cease in the vicinity of the contamination and Council must be\nnotified immediately.\nWhere remediation work is required, the applicant will be required to obtain consent for the\nremediation works.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"38","code":null,"number":"38","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved removal,\nrelocation or reconstruction of infrastructure (including ramps, footpaths, kerb and gutter,\nlight poles, kerb inlet pits, service provider pits, street trees or any other infrastructure in the\nstreet footpath area) must be paid as directed by the consent authority.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"39","code":null,"number":"39","title":"Waste management","text":"While site work is being carried out:\n1. all waste management must be undertaken in accordance with the approved waste\nmanagement plan; and\n2. upon disposal of waste, records of the disposal must be compiled and provided to the\ncertifying authority, detailing the following:\na. The contact details of the person(s) who removed the waste;\nb. The waste carrier vehicle registration;\nc. The date and time of waste collection;\nd. A description of the waste (type of waste and estimated quantity) and\nwhether the waste is to be reused, recycled or go to landfill;\ne. The address of the disposal location(s) where the waste was taken;\nf. The corresponding tip docket/receipt from the site(s) to which the waste is\ntransferred, noting date and time of delivery, description (type and quantity)\nof waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order or\nExemption, records in relation to that Order or Exemption must be maintained and provided\nto the principal certifier and Council.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"40","code":null,"number":"40","title":"Hours of work","text":"Site work must only be carried out between the following times -\n7:00am to 5:00pm on Monday to Saturday\nSite work is not to be carried out outside of these times except where there is an emergency,\nor for urgent work directed by a police officer or a public authority.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"41","code":null,"number":"41","title":"Construction Noise","text":"While building work is being carried out the certifier must ensure that any noise generated\nfrom the site is controlled in accordance with the requirements of the Acoustic DA Report,\nprepared by PKA Acoustic Consulting and dated 19 July 2024.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"42","code":null,"number":"42","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must be maintained\nin good condition in accordance with:\na) The construction site management plan approved under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development sites;\nc) Any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery, builders refuse,\nspoil and materials remain outside tree protection zones","stage":"before_cc","stage_basis":"heading","page":20},{"label":"43","code":null,"number":"43","title":"Offensive noise, dust, odour, and vibration","text":"No work must not give rise to offensive noise, odour, or vibration as defined in the Protection\nof the Environment Operations Act 1997 when measured at the nearest property boundary.","stage":"before_cc","stage_basis":"heading","page":20},{"label":"44","code":null,"number":"44","title":"Excavations and Backfilling","text":"All excavations and backfilling associated with this development consent must be executed\nsafely, and be properly guarded and protected to prevent them from being dangerous to life\nor property, and in accordance with the design of a suitably qualified Structural Engineer.\nIf an excavation extends below the level of the base of the footings of a building on an\nadjoining allotment, the person causing the excavation must:\na) preserve and protect the building from damage; and\nb) if necessary, underpin and support the building in an approved manner; and\nc) give at least seven days’ notice to the adjoining owners before excavating, or of the\nintention to excavate.\nThe principal contractor, owner builder or any person who needs to excavate and undertake\nbuilding work, must contact “Dial Before You Dig” prior to works commencing, and allow a\nreasonable period of time for the utilities to provide locations of their underground assets.\nThis condition does not apply if the person having the benefit of the development consent\nowns the adjoining land or the owner of the adjoining land has given consent in writing to that\ncondition not applying.","stage":"before_cc","stage_basis":"heading","page":20},{"label":"45","code":null,"number":"45","title":"Cut and Fill (if applicable)","text":"While building work is being carried out, the principal certifier must be satisfied all soil\nremoved from or imported to the site is managed in accordance with the following\nrequirements:\na) All excavated material removed from the site must be classified in accordance with\nthe EPA’s Waste Classification Guidelines before it is disposed of at an approved waste\nmanagement facility and the classification and the volume of material removed must be\nreported to the principal certifier.\nb) All fill material imported to the site must be Virgin Excavated Natural Material as\ndefined in Schedule 1 of the Protection of the Environment Operations Act 1997 or a\nmaterial identified as being subject to a resource recovery exemption by the NSW\nEPA.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"46","code":null,"number":"46","title":"Placement of fill","text":"Filling must not be placed in such a manner that natural drainage from adjoining land will be\nobstructed or in such a manner that surface water will be diverted.\nFurther, any alterations to the natural surface contours must not impede or divert natural\nsurface water runoff so as to cause a nuisance to adjoining property owners.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"47","code":null,"number":"47","title":"Location of stockpiles","text":"Stockpiles of soil must not be located on / near any drainage lines or easements, natural\nwatercourses or water bodies, footpath or roadway without first providing suitable protective\nmeasures adequate to protect these water bodies. All stockpiles of contaminated materials\nmust be suitably covered to prevent dust and odour nuisance.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"48","code":null,"number":"48","title":"Implementation of Site Management Plans","text":"While site work is being carried out:\na) the measures required by the construction site management plan and the erosion and\nsediment control plan (plans) must be implemented at all times, and\nb) a copy of these plans must be kept on site at all times and made available to council\nofficers upon request.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"49","code":null,"number":"49","title":"Disposal of Stormwater During Works","text":"Water seeping into any site excavations is not to be pumped into the stormwater system\nunless it complies with relevant Environmental Protection Agency and Australian and New\nZealand Environment and Conservation Council standards for water quality discharge.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"50","code":null,"number":"50","title":"Implementation of BASIX Commitments","text":"While building work is being carried out, the applicant must undertake the development\nstrictly in accordance with the commitments listed in the BASIX certificate(s) approved by this\nconsent, for the development to which the consent applies.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"51","code":null,"number":"51","title":"Stormwater Disposal","text":"Following the installation of any roof, collected stormwater runoff from the structure must be:\na) Diverted through a first flush system or leaf/debris prevention system before being\nconnected to an approved stormwater system. Before draining to the public system,\nstormwater must be connected to an approved stormwater quality improvement device in\naccordance with the approved plans.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"52","code":null,"number":"52","title":"Toilet Facilities","text":"Temporary toilet(s) must be provided and maintained on site from the time of\ncommencement of building work to completion. The number of toilets provided must be one\ntoilet per 20 persons or part thereof employed on the site at any one time.\nThe temporary toilet is to be either connected to the sewerage system or an approved septic\ntank or otherwise may be a chemical toilet supplied by a licensed contractor.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"53","code":null,"number":"53","title":"Tree Removal/Pruning","text":"All approved tree removal/Pruning is subject to all pruning works being undertaken by a\nqualified arborist with minimum Australian Qualification Framework Level 3 qualifications or\nhigher. All works are to be undertaken in accordance with the relevant provisions of AS 4373\n'Pruning of Amenity trees'.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"54","code":null,"number":"54","title":"Finished Floor Level","text":"The finished floor level of the dwelling must be a minimum level of Reduced Level 9.2 metres\nAustralian Height Datum in accordance with the approved plans.\nA survey report prepared by a Registered Surveyor confirming that the finished floor level\ncomplies with the approved plans or floor levels specified by the development consent, must\nbe provided to Principal Certifying Authority prior to the development proceeding beyond\nfloor level stage.","stage":"before_cc","stage_basis":"heading","page":23},{"label":"55","code":null,"number":"55","title":"Occupation Certificate Required","text":"An Occupation Certificate must be obtained prior to any use or occupation of the\ndevelopment.\nThe Principal Certifying Authority must be satisfied that the development has been\nconstructed in accordance with approved plans, specifications and conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"56","code":null,"number":"56","title":"Completion of landscape and tree works","text":"Before the issue of an occupation certificate, the principal certifier must be satisfied that all\nlandscape and tree-works, including pruning in accordance with AS 4373-2007 Pruning of\namenity trees and the removal of all noxious weed species, have been completed in\naccordance with the approved plans and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"57","code":null,"number":"57","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":23},{"label":"58","code":null,"number":"58","title":"Removal of waste upon completion","text":"Before the issue of an occupation certificate, the principal certifier must ensure all refuse,\nspoil and material unsuitable for use on-site is removed from the site and disposed of in\naccordance with the approved waste management plan. Written evidence of the removal\nmust be supplied to the satisfaction of the principal certifier.\nBefore the issue of a partial occupation certificate, the applicant must ensure the temporary\nstorage of any waste is carried out in accordance with the approved waste management plan\nto the principal certifier’s satisfaction.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"59","code":null,"number":"59","title":"Completion of Roads Act Approval works","text":"Before the issue of an Occupation Certificate, all approved road, footpath and/or drainage\nworks, including vehicle crossings, have been completed in the road reserve in accordance\nwith the Roads Act Approval to the satisfaction of the Council as the Roads Authority.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"60","code":null,"number":"60","title":"Stormwater/drainage works","text":"Before the issue of an Occupation Certificate, all stormwater and drainage works required to\nbe undertaken in accordance with this consent must be completed.\nThe certification/verification must be provided to the satisfaction of the Principal Certifying\nAuthority.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"61","code":null,"number":"61","title":"Water authority certification","text":"Before the issue of an Occupation Certificate, a Section 50 Application under the Hunter Water\nAct 1991 must be lodged with the Hunter Water Corporation (HWC) and details of the Notice\nof Compliance from HWC must be provided to the Certifying Authority.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"62","code":null,"number":"62","title":"Survey Certificate","text":"Before the issue of an Occupation Certificate, a Registered Surveyor must prepare a Survey\nCertificate to certify that the location of the building in relation to the allotment boundaries\ncomplies with the approved plans or as specified by this consent. The Survey Certificate must\nbe provided to the satisfaction of the Principal Certifying Authority.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"63","code":null,"number":"63","title":"Post-construction dilapidation report","text":"Prior to the issue of an occupation certificate, a post-construction dilapidation report must be\nprepared by a suitably qualified engineer, to the satisfaction of the principal certifier, detailing\nwhether:\na) After comparing the pre-construction dilapidation report to the post-construction\ndilapidation report required under this condition, there has been any structural\ndamage to any adjoining buildings; and\nb) Where there has been structural damage to any adjoining buildings, that it is a result\nof the work approved under this development consent, and\nc) A copy of the post-construction dilapidation report must be provided to Council\n(where council is not the principal certifiers or a principal certifier is not required) and\nto the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":25},{"label":"64","code":null,"number":"64","title":"Services","text":"Before the issue of an Occupation Certificate, evidence is to be provided to Council\ndemonstrating that the following reticulated services are available to each dwelling:\na) Electricity;\nb) Water;\nc) Sewer; and\nd) Gas (where available).\nShould any of the above reticulated services not be available to the development site, a\ndetailed statement is to be provided explaining why connection of the relevant service is not\npossible or practical.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"65","code":null,"number":"65","title":"Shelter-in-place Emergency Response Strategy","text":"A Shelter-in-place Emergency Response Strategy for the proposed development must be\nprovided to the Principal Certifying Authority with the occupation certificate application. The\nstrategy must include the following as a minimum:\na) Details as to how the shelter-in-place strategy will be communicated to residents and\nhow this communication will be maintained for the life of the development;\nb) Warning times and communication methods for when shelter-in-place is to be\nimplemented;\nc) Consideration of protection from weather and appropriate heating and cooling;\nd) Access to personal hygiene facilities such as a toilet;\ne) Items for self-sufficiency including sufficient drinking water, food, fire extinguishers,\nradios and torches and first aid kit;\nf) Description of the expected flood inundation at the site and the relevant surrounding\narea, including flood depths, direction of flow, velocities, hazard and specific relevant\nvulnerabilities;\ng) Consideration of and strategies for, the needs of the elderly, disabled and vulnerable\nwho may be on site;\nh) A strategy for effective flood risk management when the electricity, internet,\ntelecommunications etc., are unavailable;\ni) Detail as to how the requirements will be maintained and enforced for the life of the\ndevelopment\nNote: Digital elevation data is available from Geosciences Australia, current flood studies are\navailable on Council's website and river gauge/ tidal gauge data is available from the Bureau of\nMeteorology website.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"66","code":null,"number":"66","title":"Protection and Certification of Electrical Services","text":"All power points, fittings, electrical connections and the incoming meter box are to be located\nabove the Flood Planning Level (FPL) which is RL 9.2m AHD.\nSwitches, light fittings and power points may be located below the FPL provided they are\ncapable of being isolated by a single Residual Current Device (RCD) protected switch that is\nlocated above the FPL. Certification of these works are to be provided to the Principal\nCertifying Authority.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"67","code":null,"number":"67","title":"Restriction on Title - Affordable Housing","text":"A restriction as to user must be Registered against the title of the property in accordance with\nsection 88E of the Conveyancing Act 1919 limiting the use of the of units on proposed Lot 2 to\nbe used as affordable for 15 years. The restriction is to be registered prior to the issue of the\nOccupation Certificate or Subdivision Certificate, whichever occurs first.","stage":"before_oc","stage_basis":"heading","page":26},{"label":"68","code":null,"number":"68","title":"Driveways and car parking to be maintained","text":"All access crossings and driveways must be maintained in good order for the life of the\ndevelopment.\nThe car parking area is to be solely used for parking and not for storage of any items.","stage":"ongoing","stage_basis":"heading","page":27},{"label":"69","code":null,"number":"69","title":"Manoeuvring of Vehicles","text":"All vehicles must enter and exit the site in a forward direction","stage":"ongoing","stage_basis":"heading","page":27},{"label":"70","code":null,"number":"70","title":"Waste management and collection","text":"At all times, the management body must make arrangements for the placement of the\ngarbage bins at the kerbside for weekly collection and must ensure the return of the bins to\nthe garbage storage area as soon as practicable after collection. Waste management is to be in\naccordance with the approved waste management plan for the life of the development.","stage":"ongoing","stage_basis":"heading","page":27},{"label":"71","code":null,"number":"71","title":"Maintenance of Landscaping","text":"Landscaping must be maintained in accordance with the approved landscape plan and\nconditions of this development consent. All landscape areas must be kept free of parked\nvehicles, stored goods, garbage or waste material at all times.\nIf any of the vegetation dies or is removed, it is to be replaced with vegetation of the same\nspecies and similar maturity as the vegetation which has died or was removed.","stage":"ongoing","stage_basis":"heading","page":27},{"label":"72","code":null,"number":"72","title":"Maintenance of wastewater and stormwater treatment device/s","text":"During occupation and ongoing use of the development, the applicant must ensure all\nwastewater and stormwater treatment devices (including drainage systems, sumps and traps,\nand on-site detention) are regularly maintained to remain effective and in accordance with\nany positive covenant (if applicable) and any approved operation management plan.","stage":"ongoing","stage_basis":"heading","page":27},{"label":"73","code":null,"number":"73","title":"Location of Mechanical Ventilation","text":"During occupation and ongoing use of the building, the applicant must ensure all subsequently\ninstalled noise generating mechanical ventilation system(s) or other plant and equipment that\ngenerates noise are in an appropriate location on the site (including a soundproofed area\nwhere necessary) to ensure the noise generated does not exceed 5dBa at the boundary\nadjacent to any habitable room of an adjoining residential premises.\nSubdivision Work\nBefore issue of a subdivision works certificate","stage":"ongoing","stage_basis":"heading","page":27},{"label":"74","code":null,"number":"74","title":"Erosion and sediment controls plan","text":"Before the issue of a Subdivision Works Certificate, an erosion and sediment control plan must\nbe prepared by a suitably qualified person in accordance with the following documents and\nprovided to the certifier:\n1. the guidelines set out in 'Managing Urban Stormwater: Soils and Construction’\nprepared by Landcom (the Blue Book) (as amended from time to time), and\n2. The ‘Do it Right On-Site, Soil and Water Management for the Construction Industry'\n(Southern Sydney Regional Organisation of Councils and the Natural Heritage Trust)\n(as amended from time to time).","stage":"ongoing","stage_basis":"heading","page":28},{"label":"75","code":null,"number":"75","title":"Subdivision Works Certificate","text":"The following information must be provided to the Certifying Authority with the Subdivision\nWorks Certificate application:\na) Amended stormwater management plan which directs all stormwater generated from the\nsite to the on-site detention systems prior to leaving the site, including the internal driveway\naccess from Phillip Street.","stage":"ongoing","stage_basis":"heading","page":28},{"label":"76","code":null,"number":"76","title":"Waste Management Plan requirements","text":"Before the issue of a Subdivision Works Certificate, a waste management plan for the\ndevelopment must be prepared and provided to the certifier.","stage":"ongoing","stage_basis":"heading","page":28},{"label":"77","code":null,"number":"77","title":"Stormwater/Drainage Plans","text":"Detailed stormwater drainage plans must be prepared by a qualified Engineer in accordance\nwith the approved plans, Council’s Infrastructure Specifications and the current Australian\nRainfall and Runoff guidelines using the Hydrologic Soil Mapping data for Port Stephens\n(available from Council).\nDetails demonstrating compliance must be provided to the Certifying Authority, prior to the\nissue of a Subdivision Works Certificate.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of\nworks within an existing road reserve.","stage":"ongoing","stage_basis":"heading","page":28},{"label":"78","code":null,"number":"78","title":"Roads Act Approval","text":"Before the issue of a Subdivision Works Certificate, for construction/reconstruction of Council\ninfrastructure, including vehicular crossings, footpath, kerb and gutter, stormwater drainage,\nan application must be made for a Roadworks Permit under Section 138 of the Roads Act\n1993. The following information must be provided to Council as the Roads Authority with the\nRoads Act application:\na) Stormwater connections to public infrastructure\nb) Footpath to be designed across the full frontage of the development site within Phillip\nStreet, connecting to the existing bus stop and including kerb ramp(s).","stage":"ongoing","stage_basis":"heading","page":29},{"label":"79","code":null,"number":"79","title":"Civil engineering plans","text":"Before the issue of a Subdivision Works Certificate, civil engineering plans prepared by a\nqualified Engineer, indicating any required drainage, roads, accessways, earthworks,\npavement design, street lighting, details of line-marking, traffic management, water quality\nand quantity facilities including stormwater detention and disposal, must be prepared in\naccordance with the approved plans and Council’s Infrastructure Specifications.\nDetails demonstrating compliance must be provided to the Certifying Authority.\nNote: Under the Roads Act 1993, only the Roads Authority can approve commencement of\nworks within an existing road reserve.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"80","code":null,"number":"80","title":"Construction Site Management Plan","text":"Before the issue of a Subdivision Works Certificate, a construction site management plan must\nbe prepared, and provided to the principal certifier. The plan must include the following\nmatters:\na. The location and materials for protective fencing and hoardings on the perimeter of\nthe site;\nb. Provisions for public safety;\nc. Pedestrian and vehicular site access points and construction activity zones;\nd. Details of construction traffic management including:\ni. Proposed truck movements to and from the site;\nii. Estimated frequency of truck movements; and\niii. Measures to ensure pedestrian safety near the site;\ne. Details of bulk earthworks to be carried out;\nf. The location of site storage areas and sheds;\ng. The equipment used to carry out works;\nh. The location of a garbage container with a tight-fitting lid;\ni. Dust, noise and vibration control measures;\nj. The location of temporary toilets;\nk. The protective measures for the preservation of trees on-site and in adjoining public\nareas including measures in accordance with:\ni. AS 4970 - Protection of trees on development sites;\nii. An applicable Development Control Plan;\niii. An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on site at all times while work\nis being carried out.","stage":"ongoing","stage_basis":"heading","page":29},{"label":"81","code":null,"number":"81","title":"Retaining Walls","text":"All retaining walls within 1m of a boundary and exceeding 600mm in height must be designed\nand certified by a suitably qualified Structural Engineer. All retaining walls must be wholly\ncontained within the lot boundaries.\nDetails demonstrating compliance must be provided to the Certifying Authority prior to the\nissue of the Subdivision Works Certificate.\nCondition reasons: To ensure that retaining walls in proximity to the boundary and over a\nheight are designed and certified by a suitably qualified engineer.\nBefore issue of a subdivision certificate","stage":"ongoing","stage_basis":"heading","page":30},{"label":"82","code":null,"number":"82","title":"Surveyor’s Report","text":"Before the issue of a Subdivision Certificate, a certificate from a Registered Surveyor must be\nprovided to the Principal Certifying Authority, certifying that all drainage lines have been laid\nwithin their proposed easements, or within the appropriate lots. Certification is also to be\nprovided stating that no services or accessways encroach over the proposed boundary other\nthan as provided for by easements as created by the final plan of subdivision.","stage":"ongoing","stage_basis":"heading","page":30},{"label":"83","code":null,"number":"83","title":"Burdened Lots To Be Identified","text":"Any lots subsequently identified during construction of the subdivision as requiring restrictions\nmust also be suitably burdened","stage":"ongoing","stage_basis":"heading","page":31},{"label":"84","code":null,"number":"84","title":"Services","text":"Before the issue of a Subdivision Certificate, evidence is to be provided to Council\ndemonstrating that the following reticulated services are available to each lot:\na) Electricity.\nb) Water.\nc) Sewer.\nd) Gas (where available).\nShould any of the above reticulated services not be available to the development site, a\ndetailed statement is to be provided explaining why connection of the relevant service is not\npossible or practical.","stage":"ongoing","stage_basis":"heading","page":31},{"label":"85","code":null,"number":"85","title":"Show Easements/ Restrictions on The Plan of Subdivision","text":"The developer must acknowledge all existing easements and/or restrictions on the use of the\nland on the final plan of subdivision.","stage":"ongoing","stage_basis":"heading","page":31},{"label":"86","code":null,"number":"86","title":"Requirements for a subdivision certificate","text":"The application for Subdivision Certificate(s) must be made in accordance with the\nrequirements of Section 54 of the Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021 and Section 6.33(1) Environmental Planning and\nAssessment Act 1979.\nThe applicant will be required to submit documentary evidence that the property has been\ndeveloped in accordance with the plans approved by this development consent [16-2024-420-\n1], and of compliance with the applicable conditions of consent, prior to the issuing of a\nTorrens Plan of Subdivision.\nIn addition, one signed original copy of the original plans and/or documents, and final plan of\nsurvey/title, must be submitted to Council","stage":"ongoing","stage_basis":"heading","page":31},{"label":"87","code":null,"number":"87","title":"Subdivision Certificate","text":"The issue of a Subdivision Certificate is not to occur until all applicable conditions of this\ndevelopment consent have been satisfactorily addressed and all applicable engineering works\nare complete.","stage":"ongoing","stage_basis":"heading","page":32},{"label":"88","code":null,"number":"88","title":"Section 88B Instrument","text":"The applicant must prepare a Section 88B Instrument which incorporates the following\neasements, positive covenants and restrictions to user where necessary and in accordance\nwith the approved plans:\na) Right of access; and\nb) Easement for parking","stage":"ongoing","stage_basis":"heading","page":32},{"label":"89","code":null,"number":"89","title":"Restriction on Title - Affordable Housing","text":"A restriction as to user must be Registered against the title of the property in accordance with\nsection 88E of the Conveyancing Act 1919 limiting the use of the of units on proposed Lot 2 to\nbe used as affordable for 15 years. The restriction is to be registered prior to the issue of the\nOccupation Certificate or Subdivision Certificate, whichever occurs first.","stage":"ongoing","stage_basis":"heading","page":32},{"label":"90","code":null,"number":"90","title":"Water Authority Certification","text":"A Section 50 Application under the Hunter Water Act 1991 must be lodged with Hunter Water\nCorporation (HWC) and details of the Notice of Compliance from HWC must be provided to\nthe Certifying Authority.","stage":"ongoing","stage_basis":"heading","page":32}]});
